insert into public.indicators (
  form_version_id,
  group_id,
  code,
  original_name,
  display_name,
  description,
  subgroup,
  source_sheet,
  source_cell,
  source_row,
  source_column,
  source_cells,
  source_metadata,
  data_type,
  unit_of_measure,
  calculation_type,
  annual_aggregation_type,
  required,
  accepts_zero,
  allows_empty,
  allows_not_applicable,
  minimum_value,
  maximum_value,
  display_order,
  active,
  is_dashboard_featured,
  dashboard_default_presentation,
  dashboard_card_enabled,
  dashboard_chart_enabled
)
select
  active_form.id,
  indicator_groups.id,
  indicator_seed.code,
  indicator_seed.original_name,
  indicator_seed.display_name,
  indicator_seed.description,
  indicator_seed.subgroup,
  indicator_seed.source_sheet,
  indicator_seed.source_cell,
  indicator_seed.source_row,
  indicator_seed.source_column,
  indicator_seed.source_cells,
  indicator_seed.source_metadata::jsonb,
  indicator_seed.data_type::public.indicator_data_type,
  indicator_seed.unit_of_measure,
  indicator_seed.calculation_type::public.indicator_calculation_type,
  indicator_seed.annual_aggregation_type::public.annual_aggregation_type,
  indicator_seed.required,
  indicator_seed.accepts_zero,
  indicator_seed.allows_empty,
  indicator_seed.allows_not_applicable,
  indicator_seed.minimum_value::numeric,
  indicator_seed.maximum_value::numeric,
  indicator_seed.display_order,
  indicator_seed.active,
  indicator_seed.is_dashboard_featured,
  indicator_seed.dashboard_default_presentation,
  indicator_seed.dashboard_card_enabled,
  indicator_seed.dashboard_chart_enabled
from indicator_seed
cross join active_form
join public.indicator_groups on indicator_groups.form_version_id = active_form.id
  and indicator_groups.code = indicator_seed.group_code
on conflict (form_version_id, code) do update
set group_id = excluded.group_id,
    original_name = excluded.original_name,
    display_name = excluded.display_name,
    description = excluded.description,
    subgroup = excluded.subgroup,
    source_sheet = excluded.source_sheet,
    source_cell = excluded.source_cell,
    source_row = excluded.source_row,
    source_column = excluded.source_column,
    source_cells = excluded.source_cells,
    source_metadata = excluded.source_metadata,
    data_type = excluded.data_type,
    unit_of_measure = excluded.unit_of_measure,
    calculation_type = excluded.calculation_type,
    annual_aggregation_type = excluded.annual_aggregation_type,
    required = excluded.required,
    accepts_zero = excluded.accepts_zero,
    allows_empty = excluded.allows_empty,
    allows_not_applicable = excluded.allows_not_applicable,
    minimum_value = excluded.minimum_value,
    maximum_value = excluded.maximum_value,
    display_order = excluded.display_order,
    active = excluded.active,
    is_dashboard_featured = excluded.is_dashboard_featured,
    dashboard_default_presentation = excluded.dashboard_default_presentation,
    dashboard_card_enabled = excluded.dashboard_card_enabled,
    dashboard_chart_enabled = excluded.dashboard_chart_enabled,
    updated_at = now();

