insert into public.group_observation_definitions (form_version_id, group_id, code, label, source_range)
select active_form.id, indicator_groups.id, observation_seed.code, observation_seed.label, observation_seed.source_range
from observation_seed
cross join active_form
join public.indicator_groups on indicator_groups.form_version_id = active_form.id
  and indicator_groups.code = observation_seed.group_code
on conflict (form_version_id, code) do update
set group_id = excluded.group_id,
    label = excluded.label,
    source_range = excluded.source_range,
    active = true,
    updated_at = now();

