insert into public.indicator_relationships (
  form_version_id,
  parent_indicator_id,
  child_indicator_id,
  related_source_rows,
  display_order,
  relationship_type,
  validation_severity,
  notes
)
select
  active_form.id,
  parent_indicator.id,
  child_indicator.id,
  relationship_seed.related_source_rows,
  relationship_seed.display_order,
  relationship_seed.relationship_type,
  relationship_seed.validation_severity::public.validation_severity,
  relationship_seed.notes
from relationship_seed
cross join active_form
join public.indicators parent_indicator on parent_indicator.form_version_id = active_form.id
  and parent_indicator.source_row = relationship_seed.parent_source_row
left join public.indicators child_indicator on child_indicator.form_version_id = active_form.id
  and child_indicator.source_row = relationship_seed.child_source_row;
